from flask import Flask, request

app = Flask(__name__)

@app.route('/jobs')
def jobs():
  name = request.args.get('name')
  email = request.args.get('email')

  resp = '''
_VARS = {
  'name': '%s',
  'email': '%s'
}
_job = {
  'title': 'Web Developer',
  'description': 'We are looking for a full-time web developer...',
  'location': 'New York, NY',
  'contact_email': 'contact@example.com'
}
  ''' % (name, email)

  return resp
